/**
 * Product web addresses (/product/<slug>) are generated by the server when a
 * product is created: "<top-level category>-<english name>", e.g.
 * "men-enzo-swim-shorts". They never change afterwards (renaming a product keeps
 * its address, so shared links and search results keep working).
 */

const MAX_LENGTH = 100;

export function slugify(text: string): string {
  return text
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** "<category>-<name>", without repeating the category, cut on a whole word. */
export function productSlugBase(nameEn: string, topCategorySlug: string): string {
  const category = slugify(topCategorySlug);
  const name = slugify(nameEn);
  let slug = !name ? category : !category || name === category || name.startsWith(`${category}-`) ? name : `${category}-${name}`;
  if (slug.length > MAX_LENGTH) slug = slug.slice(0, MAX_LENGTH + 1).replace(/-[^-]*$/, '');
  return slug || 'product';
}

/** `base`, or `base-2`, `base-3`… — the first one not taken yet. */
export async function uniqueSlug(base: string, isTaken: (slug: string) => Promise<boolean>): Promise<string> {
  if (!(await isTaken(base))) return base;
  for (let n = 2; ; n++) {
    const candidate = `${base}-${n}`;
    if (!(await isTaken(candidate))) return candidate;
  }
}
